const form=document.querySelector('#onboardingForm');if(form){form.addEventListener('submit',e=>{e.preventDefault();const restaurant={name:document.querySelector('#restaurantName').value,slug:document.querySelector('#slug').value,description:document.querySelector('#description').value,cuisine:document.querySelector('#cuisine').value};localStorage.setItem('platedRestaurant',JSON.stringify(restaurant));location.href='storefront.html'});document.querySelector('#slug').addEventListener('input',e=>{e.target.value=e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,'-');document.querySelector('#available').textContent=e.target.value.length>2?'✓ Available':'Choose a name'})}
const saved=JSON.parse(localStorage.getItem('platedRestaurant')||'null');if(saved&&document.querySelector('.store-brand')){document.querySelector('.store-brand').innerHTML=saved.name.toUpperCase().replace(' ',' <i>✽</i> ');document.title=saved.name+' — Order online';const hero=document.querySelector('.store-hero p');hero.textContent=saved.cuisine.toUpperCase();}
const cart=[];const count=document.querySelector('#cartCount');const drawer=document.querySelector('#cartDrawer');function renderCart(){if(!drawer)return;const lines=document.querySelector('#cartLines');lines.innerHTML=cart.length?cart.map(x=>`<div class="cart-line"><span>${x.name} × ${x.qty}</span><b>₹ ${x.price*x.qty}</b></div>`).join(''):'<p class="empty">Your bag is waiting for something delicious.</p>';const total=cart.reduce((s,x)=>s+x.price*x.qty,0);document.querySelector('#cartTotal').textContent='₹ '+total;if(count)count.textContent=cart.reduce((s,x)=>s+x.qty,0)}document.querySelectorAll('.add-item').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.dish-card'),name=card.dataset.item,price=+card.dataset.price,existing=cart.find(x=>x.name===name);existing?existing.qty++:cart.push({name,price,qty:1});btn.textContent='Added ✓';renderCart()}));if(document.querySelector('#cartButton'))document.querySelector('#cartButton').onclick=()=>drawer.classList.add('open');if(document.querySelector('#closeCart'))document.querySelector('#closeCart').onclick=()=>drawer.classList.remove('open');renderCart();const accept=document.querySelector('.accept-order');if(accept)accept.onclick=()=>{accept.textContent='Accepted ✓';accept.style.background='#749a36';accept.disabled=true};
